Q: How do I get my hyperlink leading to another page to play an audio sound when I click it? A: <p>The solution to the problem you raise involves “tricking” the visitor. Let's see how:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>document.addEventListener('DOMContentLoaded', init);

function init() {
   document.getElementById( "false_hiperlink" ).addEventListener( "click", function() {
      play_sound();
   });
}

function play_sound() {
    const audio = new Audio( "beep.mp3" );
    audio.play();          

      //  we add a listener to call the “goTo()” method when playback ends.     
    audio.addEventListener( "ended", () =&gt; {
        goTo();
    });
}

function goTo() {
    window.location.href = "other_html.html";
}</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>/* we can change the color of the text 
   so that it looks like a hyperlink. */
#false_hiperlink {
   color : blue;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;!-- replace hyperlink by a "p" element --&gt;
&lt;!-- we add “tabindex=”0", so that our element is accessible --&gt;
&lt;p tabindex="0" id="false_hiperlink"&gt; go to -&gt; &lt;/p&gt;
&lt;center&gt; &lt;a href="Page/Directory" tabindex="0" style="color:green;"&gt; (The Page) &lt;/a&gt; </code></pre>
</div>
</div>
</p>
